def path_xyz(knots,speed=.012,note='brush path',fps=10):
    knots=np.asarray(knots)
    pts=[]
    for a,b in zip(knots[:-1],knots[1:]):
        n=max(1,int(np.ceil(np.linalg.norm(b[:2]-a[:2])/(speed*.05))))
        pts.extend(np.linspace(a,b,n+1)[1:])
    pts=np.array(pts)
    return execute(np.c_[pts,np.tile(quat,(len(pts),1))],note,fps=fps)

def testline(x, depths, note):
    dip()
    knots=[[x,y,.0202-d] for y,d in depths]
    move([x,depths[0][0],.055],note='practice approach')
    move(knots[0],speed=.02,hold=0,note='touch')
    path_xyz(knots,note=note,fps=20)
    move([*knots[-1][:2],.06],hold=.3,note='lift')
    park()
    return snapshot(note)

